    .{ .name = "bootchartd", .text = "\nUsage: bootchartd start [PROG ARGS]|stop|init\n\nCreate /var/log/bootchart.tgz with boot chart data\n\nstart: start background logging; with PROG, run PROG, then kill logging with USR1\nstop: send USR1 to all bootchartd processes\ninit: start background logging; stop when getty/xdm is seen (for init scripts)\nUnder PID 1: as init, then exec $bootchart_init, /init, /sbin/init\n" },
    .{ .name = "brctl", .text = "\nUsage: brctl COMMAND [BRIDGE [ARGS]]\n\nManage ethernet bridges\nCommands:\n\tshow [BRIDGE]...\tShow bridges\n\taddbr BRIDGE\t\tCreate BRIDGE\n\tdelbr BRIDGE\t\tDelete BRIDGE\n\taddif BRIDGE IFACE\tAdd IFACE to BRIDGE\n\tdelif BRIDGE IFACE\tDelete IFACE from BRIDGE\n\tshowmacs BRIDGE\t\t\tList MAC addresses\n\tshowstp\tBRIDGE\t\t\tShow STP info\n\tstp BRIDGE 1/yes/on|0/no/off\tSet STP on/off\n\tsetageing BRIDGE SECONDS\tSet ageing time\n\tsetfd BRIDGE SECONDS\t\tSet bridge forward delay\n\tsethello BRIDGE SECONDS\t\tSet hello time\n\tsetmaxage BRIDGE SECONDS\tSet max message age\n\tsetbridgeprio BRIDGE PRIO\tSet bridge priority\n\tsetportprio BRIDGE IFACE PRIO\tSet port priority\n\tsetpathcost BRIDGE IFACE COST\tSet path cost\n" },
    .{ .name = "bunzip2", .text = "\nUsage: bunzip2 [-cfk] [FILE]...\n\nDecompress FILEs (or stdin)\n\n\t-c\tWrite to stdout\n\t-f\tForce\n\t-k\tKeep input files\n\t-t\tTest integrity\n" },
    .{ .name = "busybox", .text = "BusyBox is copyrighted by many authors between 1998-2015.\nLicensed under GPLv2. See source distribution for detailed\ncopyright notices.\n\nUsage: busybox [function [arguments]...]\n   or: busybox --list[-full]\n   or: busybox --show SCRIPT\n   or: busybox --install [-s] [DIR]\n   or: function [arguments]...\n\n\tBusyBox is a multi-call binary that combines many common Unix\n\tutilities into a single executable.  Most people will create a\n\tlink to busybox for each function they wish to use and BusyBox\n\twill act like whatever it was invoked as.\n\nCurrently defined functions:\n\t[, [[, acpid, add-shell, addgroup, adduser, adjtimex, arch, arp,\n\tarping, ascii, ash, awk, base32, base64, basename, bc, beep,\n\tblkdiscard, blkid, blockdev, bootchartd, brctl, bunzip2, bzcat, bzip2,\n\tcal, cat, chat, chattr, chgrp, chmod, chown, chpasswd, chpst, chroot,\n\tchrt, chvt, cksum, clear, cmp, comm, conspy, cp, cpio, crc32, crond,\n\tcrontab, cryptpw, cttyhack, cut, date, dc, dd, deallocvt, delgroup,\n\tdeluser, depmod, devmem, df, dhcprelay, diff, dirname, dmesg, dnsd,\n\tdnsdomainname, dos2unix, dpkg, dpkg-deb, du, dumpkmap, dumpleases,\n\techo, ed, egrep, eject, env, envdir, envuidgid, ether-wake, expand,\n\texpr, factor, fakeidentd, fallocate, false, fatattr, fatlabel, fbset,\n\tfbsplash, fdflush, fdformat, fdisk, fgconsole, fgrep, find, findfs,\n\tflock, fold, free, freeramdisk, fsck, fsck.minix, fsfreeze, fstrim,\n\tfsync, ftpd, ftpget, ftpput, fuser, getfattr, getopt, getty, grep,\n\tgroups, gunzip, gzip, halt, hd, hdparm, head, hexdump, hexedit, hostid,\n\thostname, httpd, hush, hwclock, i2cdetect, i2cdump, i2cget, i2cset,\n\ti2ctransfer, id, ifconfig, ifdown, ifenslave, ifplugd, ifup, inetd,\n\tinit, insmod, install, ionice, iostat, ip, ipaddr, ipcalc, ipcrm, ipcs,\n\tiplink, ipneigh, iproute, iprule, iptunnel, join, kbd_mode, kill,\n\tkillall, killall5, klogd, last, less, link, linux32, linux64, linuxrc,\n\tln, loadfont, loadkma