/// Applets whose reference binary omitted usage; rendered from //usage: comments.
pub const source_fallback = [_][]const u8{
    "ar",
    "bash",
    "bbconfig",
    "chcon",
    "devfsd",
    "flash_eraseall",
    "flash_lock",
    "flash_unlock",
    "flashcp",
    "getenforce",
    "getsebool",
    "inotifyd",
